package com.orderengine.client.payment;  import com.orderengine.client.payment.api.PaymentsApi; import com.orderengine.client.payment.model.AuthorizeRequest; import com.orderengine.client.payment.model.CaptureRequest; import com.orderengine.client.payment.model.PaymentResponse; import com.orderengine.client.payment.model.RefundRequest; import com.orderengine.client.payment.model.RefundResponse; import org.springframework.stereotype.Component;  @Component public class PaymentServiceClient {      private final PaymentsApi paymentsApi;      public PaymentServiceClient(PaymentsApi paymentsApi) {         this.paymentsApi = paymentsApi;     }      /**      * Authorize a payment      *      * @param idempotencyKey unique identifier for the request      * @param authorizeRequest payment authorization details      * @return payment response with authorization details      */     public PaymentResponse authorize(String idempotencyKey, AuthorizeRequest authorizeRequest) {         return paymentsApi.authorize(idempotencyKey, authorizeRequest);     }      /**      * Capture a previously authorized payment      *      * @param paymentId unique identifier of the payment to capture      * @param idempotencyKey unique identifier for the request      * @param captureRequest capture details (optional)      * @return payment response with capture details      */     public PaymentResponse capture(String paymentId, String idempotencyKey, CaptureRequest captureRequest) {         return paymentsApi.capture(paymentId, idempotencyKey, captureRequest);     }      /**      * Retrieve payment details      *      * @param paymentId unique identifier of the payment      * @return payment response with payment details      */     public PaymentResponse getPayment(String paymentId) {         return paymentsApi.getPayment(paymentId);     }      /**      * Refund a captured payment      *      * @param paymentId unique identifier of the payment to refund      * @param idempotencyKey unique identifier for the request      * @param refundRequest refund details      * @return refund response      */     public RefundResponse refund(String paymentId, String idempotencyKey, RefundRequest refundRequest) {         return paymentsApi.refund(paymentId, idempotencyKey, refundRequest);     }      /**      * Void a previously authorized payment      *      * @param paymentId unique identifier of the payment to void      * @param idempotencyKey unique identifier for the request      * @return payment response with void details      */     public PaymentResponse voidAuthorization(String paymentId, String idempotencyKey) {         return paymentsApi.voidAuthorization(paymentId, idempotencyKey);     } }